        demands = [0] * (mx + 1 if mx >= 0 else 1)

    if capacity is None:
        s = 0
        for c in customers:
            if c != depot:
                s += demands[c] if c < len(demands) else 0
        capacity = s if s > 0 else 1

    def point(i):
        if coords is None or i < 0 or i >= len(coords):
            return (float(i), 0.0)
        p = coords[i]
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            return (float(p[0]), float(p[1]))
        return (float(i), 0.0)

    def dist(a, b):
        pa = point(a)
        pb = point(b)
        dx = pa[0] - pb[0]
        dy = pa[1] - pb[1]
        return (dx * dx + dy * dy) ** 0.5

    def load(route):
        s = 0
        for c in route:
            if c < len(demands):
                s += demands[c]
        return s

    def cost(route):
        if not route:
            return 0.0
        c = dist(depot, route[0])
        for i in range(len(route) - 1):
            c += dist(route[i], route[i + 1])
        c += dist(route[-1], depot)
        return c

    customers = [c for c in customers if c != depot]
    if not customers:
        return []

    order = sorted(customers, key=lambda x: (point(x)[0], point(x)[1], x))
    routes = []
    cur = []
    cur_load = 0
    for c in order:
        d = demands[c] if c < len(demands) else 0
        if d > capacity:
            routes.append([c])
            continue
        if cur and cur_load + d > capacity:
            routes.append(cur)
            cur = [c]
            cur_load = d
        else:
            cur.append(c)
            cur_load += d
    if cur:
        routes.append(cur)

    def best_insert(route, c):
        best_k = 0
        best_delta = None
        prev = depot
        for k in range(len(route) + 1):
            nxt = depot if k == len(route) else route[k]
            delta = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
            if best_delta is None or delta < best_delta:
                best_delta = delta
                best_k = k
            if k < len(route):
                prev = route[k]
        return best_k, best_delta

    changed = True
    while changed:
        changed = False

        for ri in range(len(routes)):
            r = routes[ri]
            if len(r) < 4:
                continue
            base = cost(r)
            best_gain = 0.0
            best_i = best_j = None
            for i in range(len(r) - 1):
                for j in range(i + 2, len(r)):
                    if i == 0 and j == len(r) - 1:
                        continue
                    nr = r[:i + 1] + list(reversed(r[i + 1:j + 1])) + r[j + 1:]
                    gain = base - cost(nr)
                    if gain > best_gain + 1e-12:
                        best_gain = gain
                        best_i, best_j = i, j
            if best_i is not None:
                routes[ri] = r[:best_i + 1] + list(reversed(r[best_i + 1:best_j + 1])) + r[best_j + 1:]
                changed = True

        if changed:
            continue

        for i in range(len(routes)):
            if changed:
                break
            for j in range(len(routes)):
                if i == j:
                    continue
                ra = routes[i]
                rb = routes[j]
                if not ra:
                    continue
                la = load(ra)
                lb = load(rb)
                for idx, c in enumerate(ra):
                    d = demands[c] if c < len(demands) else 0
                    if lb + d > capacity:
                        continue
                    new_ra = ra[:idx] + ra[idx + 1:]
                    if not new_ra:
                        continue
                    pos, _ = best_insert(rb, c)
                    new_rb = rb[:pos] + [c] + rb[pos:]
                    if cost(new_ra) + cost(new_rb) + 1e-12 < cost(ra) + cost(rb):
                        routes[i] = new_ra
                        routes[j] = new_rb
                        changed = True
                        break
                if changed:
                    break

        if changed:
            continue

        best = None
        best_gain = 0.0
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                ra = routes[i]
                rb = routes[j]
                if load(ra) + load(rb) > capacity:
                    continue
                olds = cost(ra) + cost(rb)
                cand = [ra + rb, rb + ra, list(reversed(ra)) + rb, ra + list(reversed(rb))]
                for m in cand:
                    gain = olds - cost(m)
                    if gain > best_gain + 1e-12:
                        best_gain = gain
                        best = (i, j, m)
        if best is not None:
            i, j, m = best
            if i > j:
                i, j = j, i
            routes[i] = m
            routes.pop(j)
            changed = True

    seen = {}
    out = []
    for r in routes:
        nr = []
        s = 0
        for c in r:
            if c == depot:
                continue
            if seen.get(c, 0) == 0:
                nr.append(c)
                seen[c] = 1
                if c < len(demands):
                    s += demands[c]
        if nr:
            out.append(nr)

    for c in customers:
        if seen.get(c, 0) == 0:
            out.append([c])

    final = []
    for r in out:
        cur = []
        cur_load = 0
        for c in r:
            d = demands[c] if c < len(demands) else 0
            if cur and cur_load + d > capacity:
                final.append(cur)
                cur = [c]
                cur_load = d
            else:
                cur.append(c)
                cur_load += d
        if cur:
            final.append(cur)

    return final
